add_action( 'woocommerce_thankyou', 'perfectpixel_share_purchase_buttons', 15 );

function perfectpixel_share_purchase_buttons( $order_id ) {
	$order = wc_get_order( $order_id );
	if ( ! $order || $order->has_status( 'failed' ) ) {
		return;
	}
	$names = array();
	foreach ( $order->get_items() as $item ) {
		$names[] = $item->get_name();
	}
	$text = sprintf( '{{share_text}}', implode( ', ', array_slice( $names, 0, 3 ) ) );
	$url  = home_url( '/' );

	$x  = add_query_arg( array( 'text' => rawurlencode( $text ), 'url' => rawurlencode( $url ) ), 'https://x.com/intent/tweet' );
	$fb = add_query_arg( 'u', rawurlencode( $url ), 'https://www.facebook.com/sharer/sharer.php' );

	printf(
		'<section class="perfectpixel-share-purchase" style="margin:2em 0"><h2>%1$s</h2><p><a class="button" href="%2$s" target="_blank" rel="noopener">X</a> <a class="button" href="%3$s" target="_blank" rel="noopener">Facebook</a></p></section>',
		esc_html( '{{share_title}}' ),
		esc_url( $x ),
		esc_url( $fb )
	);
}
